<?php
// Iniciar buffer de salida para evitar errores de headers
ob_start();
session_start();

// Incluir configuración y header
require_once 'config/header.php';

// Verificar sesión
if (!isset($_SESSION['usuario_id'])) {
    header('Location: login.php');
    exit();
}
$tipo_documento = 'FACTURA'; // Valor por defecto
if (isset($_GET['f'])) {
    $tipo_documento = 'FACTURA';
} elseif (isset($_GET['o'])) {
    $tipo_documento = 'OFERTA';
}

// Obtener configuración del sistema
try {
    $db = Database::getConnection();

    // Obtener configuración (Logo, etc.)
    $sql_config = "SELECT * FROM configuracion_sistema LIMIT 1";
    $stmt_config = $db->query($sql_config);
    $config = $stmt_config->fetch();

    // Lógica del Logo
    $logo_base64 = '';
    if (isset($config['logo'])) {
        $logo_db = trim($config['logo']);
        if (!empty($logo_db) && $logo_db !== 'null' && $logo_db !== 'NULL') {
            if (strpos($logo_db, 'data:image/') === 0) {
                $logo_base64 = $logo_db;
            } else {
                $decoded = @base64_decode($logo_db, true);
                if ($decoded !== false && strlen($decoded) > 100) {
                    $image_info = @getimagesizefromstring($decoded);
                    if ($image_info !== false) {
                        $logo_base64 = 'data:' . $image_info['mime'] . ';base64,' . $logo_db;
                    }
                }
            }
        }
    }
    // Fallback logo local
    if (empty($logo_base64)) {
        $logo_path = 'assets/logov.png';
        if (file_exists($logo_path)) {
            $image_info = @getimagesize($logo_path);
            if ($image_info !== false) {
                $image_data = @file_get_contents($logo_path);
                if ($image_data !== false) {
                    $logo_base64 = 'data:' . $image_info['mime'] . ';base64,' . base64_encode($image_data);
                }
            }
        }
    }
    // Fallback SVG
    if (empty($logo_base64)) {
		$svg_content = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="128" height="128" xml:space="preserve" version="1.1" viewBox="0 0 128 128">
	  <image width="128" height="128" xlink:href="data:image/png;base64,"/>
</svg>';
        $logo_base64 = 'data:image/svg+xml;base64,' . base64_encode($svg_content);
    }

} catch (Exception $e) {
    $config = [];
    $logo_base64 = '';
}

// Vaciar el buffer de salida
ob_end_flush();
