        .export-modal-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 15px 20px;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .export-modal-body {
            padding: 15px;
            display: flex;
            flex-direction: column;
            gap: 5px;
        }

        .export-modal-body .export-dropdown-item {
            background: transparent;
            border: none;
            padding: 14px 20px;
            font-size: 18px;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 12px;
            color: #bdc3c7;
            transition: all 0.25s ease;
            text-align: left;
            border-left: 3px solid transparent;
            border-radius: 6px;
            margin: 2px 0;
            width: 100%;
        }

        .export-modal-body .export-dropdown-item:hover {
            background: rgba(52, 152, 219, 0.2);
            transform: translateX(5px);
            border-left-color: #3498db;
            color: white;
        }

        .export-modal-body .export-dropdown-item i {
