<script src="js/mousetrap.min.js"></script>
<script>
    // Variables globales
    let paginaActual = 1;
    const totalPaginas = 1;
    
    // Sidebar functionality
    const sidebar = document.getElementById('sidebar');
    const toggleSidebarBtn = document.getElementById('toggleSidebar');
    const sidebarToggle = document.getElementById('sidebarToggle');
    const body = document.body;

    function toggleSidebar() {
        sidebar.classList.toggle('collapsed');
        body.classList.toggle('sidebar-expanded');
        
        const icon = toggleSidebarBtn.querySelector('i');
        if (sidebar.classList.contains('collapsed')) {
            icon.className = 'fas fa-chevron-right';
        } else {
            icon.className = 'fas fa-chevron-left';
        }
        
        localStorage.setItem('sidebarCollapsed', sidebar.classList.contains('collapsed'));
    }

    toggleSidebarBtn.addEventListener('click', toggleSidebar);
    sidebarToggle.addEventListener('click', toggleSidebar);

    // Load sidebar state from localStorage
    document.addEventListener('DOMContentLoaded', () => {
        const savedTheme = localStorage.getItem('factura-theme') || 'black';
        setTheme(savedTheme);
        
        const isCollapsed = localStorage.getItem('sidebarCollapsed') === 'true';
        if (isCollapsed) {
            sidebar.classList.add('collapsed');
            body.classList.remove('sidebar-expanded');
            toggleSidebarBtn.querySelector('i').className = 'fas fa-chevron-right';
        } else {
            sidebar.classList.remove('collapsed');
            body.classList.add('sidebar-expanded');
            toggleSidebarBtn.querySelector('i').className = 'fas fa-chevron-left';
        }
        
        updateThemeButtons(savedTheme);
    });

    function setTheme(theme) {
        document.documentElement.setAttribute('data-theme', theme);
        localStorage.setItem('factura-theme', theme);
        updateThemeButtons(theme);
        
        document.querySelectorAll('.invoice-container').forEach(container => {
            container.setAttribute('data-theme', theme);
        });
    }

    function updateThemeButtons(theme) {
        document.querySelectorAll('.theme-btn').forEach(btn => {
            btn.classList.remove('active');
        });
        
        const activeBtn = document.querySelector(`.theme-btn.theme-${theme}`);
        if (activeBtn) {
            activeBtn.classList.add('active');
        }
    }

    // FUNCIONES DE IMPRESIÓN
    function imprimirFactura() {
        Swal.fire({
            title: '<i class="fas fa-print mr-2"></i> Configuración de impresión',
            html: `
                <div style="text-align: left; color: #e5e7eb;">
                    <p style="margin-bottom: 5px; color: #60a5fa; font-size: 15px;">
                        <i class="fas fa-cog mr-1"></i> <strong>Configuración recomendada:</strong>
                    </p>
                    
                    <div style="margin-bottom: 5px; padding: 10px; background: #1f2937; border-radius: 6px; border: 1px solid #374151;">
                        <div style="display: flex; align-items: center; gap: 5px; margin-bottom: 8px;">
                            <i class="fas fa-expand-alt" style="color: #60a5fa; width: 20px;"></i>
                            <div>
                                <span style="color: #9ca3af; width: 100px; display: inline-block;">Tamaño:</span>
                                <strong style="color: #f3f4f6;">Carta (8.5x11 pulgadas)</strong>
                            </div>
                        </div>
                        
                        <div style="display: flex; align-items: center; gap: 10px;">
                            <i class="fas fa-file-signature" style="color: #60a5fa; width: 20px;"></i>
                            <div>
                                <span style="color: #9ca3af; width: 200px; display: inline-block;">Encabezados/pies:</span>
                                <strong style="color: #f3f4f6;">Desactivar</strong>
                            </div>
                        </div>
                    </div>
                    
                    <div style="margin-top: 15px; padding: 10px; background: #0f766e20; border-radius: 6px; border-left: 4px solid #14b8a6; border: 1px solid #374151;">
                        <div style="display: flex; align-items: center; gap: 8px;">
                            <i class="fas fa-clipboard-check" style="color: #5eead4;"></i>
                            <div>
                                <small style="color: #a7f3d0; font-weight: 500;">
                                    Se imprimirá el modelo de factura en blanco
                                </small>
                            </div>
                        </div>
                    </div>
                </div>
            `,
            icon: 'info',
            iconColor: '#3b82f6',
            showCancelButton: true,
            confirmButtonColor: '#2563eb',
            cancelButtonColor: '#6b7280',
            confirmButtonText: '<i class="fas fa-print mr-2"></i> Imprimir Modelo',
            cancelButtonText: '<i class="fas fa-times mr-2"></i> Cancelar',
            reverseButtons: true,
            width: 600,
            background: '#111827',
            color: '#f9fafb',
            backdrop: 'rgba(0, 0, 0, 0.8)'
        }).then((result) => {
            if (result.isConfirmed) {
                Swal.fire({
                    title: '<i class="fas fa-spinner fa-spin mr-2"></i> Preparando...',
                    html: '<p style="color:#d1d5db">Preparando modelo para impresión</p>',
                    allowOutsideClick: false,
                    showConfirmButton: false,
                    background: '#111827',
                    color: '#f9fafb',
                    timer: 800,
                    didClose: () => {
                        prepararParaImpresion();
                        
                        setTimeout(() => {
                            window.print();
                            
                            setTimeout(() => {
                                restaurarDespuesImpresion();
                            }, 500);
                        }, 500);
                    }
                });
            }
        });
    }

    function prepararParaImpresion() {
        document.querySelectorAll('.invoice-container').forEach(container => {
            container.style.display = 'block';
        });
        
        document.querySelectorAll('.no-print').forEach(el => {
            el.style.display = 'none';
        });
        
        document.body.classList.add('printing');
    }
    
    function restaurarDespuesImpresion() {
        document.querySelectorAll('.no-print').forEach(el => {
            el.style.display = '';
        });
        
        document.body.classList.remove('printing');
    }
    
    function activarModoImpresion() {
        document.querySelectorAll('.invoice-container').forEach(el => {
            el.dataset.display = el.style.display;
            el.style.display = 'block';
        });

        document.querySelectorAll('.no-print').forEach(el => {
            el.dataset.display = el.style.display;
            el.style.display = 'none';
        });
    }

    function restaurarModoImpresion() {
        document.querySelectorAll('[data-display]').forEach(el => {
            el.style.display = el.dataset.display || '';
            delete el.dataset.display;
        });
    }

    // FUNCIONES DE EXPORTACIÓN SIMPLIFICADAS PARA MODELO
    function exportarPDF() {
        Swal.fire({
            title: '<i class="fas fa-file-export"></i> Exportar a PDF',
            icon: 'info',
            iconColor: '#3b82f6',
            html: `
                <div style="text-align:left; color:#e5e7eb">
                    <p style="color:#60a5fa;">Exportando modelo de factura en blanco</p>
                </div>
            `,
            showCancelButton: true,
            confirmButtonText: '<i class="fas fa-file-pdf me-1"></i> Generar PDF',
            cancelButtonText: '<i class="fas fa-times me-1"></i> Cancelar',
            width: 450,
            background: '#111827',
            color: '#f9fafb',
            confirmButtonColor: '#2563eb'
        }).then(({ isConfirmed }) => {
            if (!isConfirmed) return;

            Swal.fire({
                title: 'Generando PDF',
                html: 'Ajustando documento...',
                allowOutsideClick: false,
                background: '#111827',
                color: '#f9fafb',
                didOpen: () => Swal.showLoading()
            });

            activarModoImpresion();

            setTimeout(() => {
                const options = {
                    margin: [0.1, 0.5, 0.25, 0.5],
                    filename: `Modelo_<?php echo $tipo_documento; ?>_${new Date().toISOString().slice(0,10)}.pdf`,
                    html2canvas: { scale: 2, useCORS: true, backgroundColor: '#FFFFFF' },
                    jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' },
                    image: { type: 'jpeg', quality: 0.98 }
                };

                html2pdf()
                    .set(options)
                    .from(document.getElementById('facturaContainer'))
                    .save()
                    .then(() => {
                        Swal.fire({
                            icon: 'success',
                            title: 'PDF generado',
                            text: 'El archivo se descargó correctamente',
                            timer: 2000,
                            showConfirmButton: false
                        });
                    })
                    .catch(err => {
                        Swal.fire({
                            icon: 'error',
                            title: 'Error',
                            text: 'Error al generar PDF',
                            confirmButtonText: 'Aceptar'
                        });
                    })
                    .finally(() => {
                        restaurarModoImpresion();
                    });
            }, 500);
        });
    }

    function exportarExcel() {
        Swal.fire({
            title: 'Generando Excel',
            text: 'Preparando modelo...',
            allowOutsideClick: false,
            background: '#111827',
            color: '#f9fafb',
            didOpen: () => Swal.showLoading()
        });
        
        const facturaData = [
            ['MODELO DE FACTURA EN BLANCO'],
            ['Fecha: ' + new Date().toLocaleDateString()],
            [''],
            ['DATOS DEL CLIENTE'],
            ['Nombre: ', ''],
            ['Cuenta Cliente: ', ''],
            ['REUP: ', ''],
            ['Dirección: ', ''],
            ['Contrato No: ', ''],
            ['Teléfono: ', ''],
            ['Email: ', ''],
            [''],
            ['DATOS DE FACTURACIÓN'],
            ['Forma de Pago: ', ''],
            ['Facturado por: ', ''],
            ['Contabilizado por: ', ''],
            [''],
            ['DETALLES DE LA FACTURA'],
            ['#', 'Código', 'Servicio', 'Cantidad', 'Precio Unit.', 'Total']
        ];
        
        for (let i = 1; i <= 18; i++) {
            facturaData.push([i, '', '', '', '', '']);
        }
        
        facturaData.push(['']);
        facturaData.push(['SUBTOTAL:', '', '', '', '', '']);
        facturaData.push(['Dscto./Increm.:', '', '', '', '', '']);
        facturaData.push(['TOTAL:', '', '', '', '', '']);
        
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet(facturaData);
        
        const wscols = [{wch: 5}, {wch: 10}, {wch: 40}, {wch: 10}, {wch: 12}, {wch: 12}];
        ws['!cols'] = wscols;
        
        XLSX.utils.book_append_sheet(wb, ws, 'Modelo Factura');
        XLSX.writeFile(wb, 'Modelo_Factura.xlsx');
        
        Swal.close();
        Swal.fire({
            title: '¡Éxito!',
            text: 'Excel exportado correctamente',
            icon: 'success',
            timer: 2000,
            showConfirmButton: false
        });
    }

    function exportarWord() {
