            didOpen: () => Swal.showLoading()
        });
        
        let htmlContent = `
        <!DOCTYPE html>
        <html>
        <head><meta charset="UTF-8"><title>Modelo Factura</title>
        <style>body{font-family:Arial;margin:20px;} table{width:100%;border-collapse:collapse;} th,td{border:1px solid #000;padding:5px;} th{background:#333;color:#white;}</style>
