    function exportarCSV() {
        Swal.fire({
            title: 'Generando CSV',
            text: 'Preparando datos...',
            allowOutsideClick: false,
            background: '#111827',
            color: '#f9fafb',
            didOpen: () => Swal.showLoading()
        });
        
        let csvContent = "MODELO DE FACTURA EN BLANCO\r\n";
        csvContent += "Fecha: , \r\n\r\n";
        csvContent += "DATOS DEL CLIENTE\r\n";
        csvContent += "Nombre: , \r\n";
