        for (let i = 1; i <= 18; i++) {
            csvContent += i + ",, , , , \r\n";
        }
        
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        saveAs(blob, 'Modelo_Factura.csv');
        
        Swal.close();
        Swal.fire({
            title: '¡Éxito!',
            text: 'CSV exportado correctamente',
            icon: 'success',
            timer: 2000,
            showConfirmButton: false
