        txtContent += "DATOS DEL CLIENTE\n";
        txtContent += "-".repeat(40) + "\n";
        txtContent += "Nombre: _________________________\n";
        txtContent += "Cuenta Cliente: _________________________\n";
        txtContent += "REUP: _________________________\n";
        txtContent += "Dirección: _________________________\n\n";
        txtContent += "-".repeat(80) + "\n";
        txtContent += "DETALLES DE LA FACTURA\n";
        txtContent += "-".repeat(80) + "\n";
        
        for (let i = 1; i <= 18; i++) {
            txtContent += `${i}.      __________    __________________________________    ______    $________    $________\n`;
        }
        
        txtContent += "-".repeat(80) + "\n";
        txtContent += "SUBTOTAL: $ ____________\n";
        txtContent += "TOTAL: $ ____________\n";
