    // Funciones para el modal de exportación
    function abrirModalExportacion() {
        document.getElementById('modalExportacion').style.display = 'flex';
    }

    function cerrarModalExportacion() {
        document.getElementById('modalExportacion').style.display = 'none';
    }

    window.onclick = function(event) {
        const modal = document.getElementById('modalExportacion');
        if (event.target == modal) {
            cerrarModalExportacion();
        }
    }

    document.addEventListener('keydown', function(event) {
        if (event.key === 'Escape') {
            const modal = document.getElementById('modalExportacion');
            if (modal.style.display === 'flex') {
                cerrarModalExportacion();
            }
        }
    });

    // Estilos CSS fijos para modo oscuro
    const style = document.createElement('style');
    style.textContent = `
        .swal2-popup {
            background: #1f2937 !important;
            border: 1px solid #374151 !important;
            border-radius: 8px !important;
            color: #f9fafb !important;
        }
        .swal2-title { color: #f9fafb !important; }
        .swal2-html-container { color: #d1d5db !important; }
        .swal2-confirm { background-color: #3b82f6 !important; }
        .swal2-cancel { background-color: #6b7280 !important; color: #f9fafb !important; }
        .swal2-close { color: #9ca3af !important; }
        .swal2-close:hover { color: #f3f4f6 !important; }
    `;
    document.head.appendChild(style);
</script>

<!-- Modal de Exportación -->
<div id="modalExportacion" class="export-modal" style="display: none;">
    <div class="export-modal-content">
        <div class="export-modal-header">
            <h3 style="margin: 0; color: white; font-size: 16px;">Seleccione el formato</h3>
            <button onclick="cerrarModalExportacion()" style="background: transparent; border: none; color: #9ca3af; cursor: pointer; font-size: 20px;">&times;</button>
        </div>
        <div class="export-modal-body">
            <button onclick="exportarPDF(); cerrarModalExportacion()" class="export-dropdown-item export-pdf" style="width: 100%;">
                <i class="fas fa-file-pdf"></i>
                <span>Exportar a PDF</span>
            </button>
            <button onclick="exportarExcel(); cerrarModalExportacion()" class="export-dropdown-item export-excel" style="width: 100%;">
                <i class="fas fa-file-excel"></i>
                <span>Exportar a Excel</span>
            </button>
            <button onclick="exportarWord(); cerrarModalExportacion()" class="export-dropdown-item export-word" style="width: 100%;">
                <i class="fas fa-file-word"></i>
                <span>Exportar a Word</span>
            </button>
            <button onclick="exportarCSV(); cerrarModalExportacion()" class="export-dropdown-item export-csv" style="width: 100%;">
                <i class="fas fa-file-csv"></i>
                <span>Exportar a CSV</span>
            </button>
            <button onclick="exportarTXT(); cerrarModalExportacion()" class="export-dropdown-item" style="width: 100%;">
                <i class="fas fa-file-alt"></i>
                <span>Exportar a TXT</span>
            </button>
        </div>
    </div>
</div>
